import ExcelJS from "exceljs"; import fs from "node:fs";
function cellText(v){if(v==null)return"";if(typeof v==="string")return v.replace(/\s+/g," ").trim();if(typeof v==="number")return Number.isFinite(v)?String(v):"";if(typeof v==="boolean")return v?"true":"false";if(v instanceof Date)return v.toISOString().slice(0,10);if(typeof v==="object"){if(Array.isArray(v.richText))return v.richText.map(p=>p.text??"").join("").replace(/\s+/g," ").trim();if(typeof v.text==="string")return cellText(v.text);if("result"in v&&v.result!=null&&v.result!=="")return cellText(v.result);if(typeof v.formula==="string")return "="+v.formula;}return""}
function trim(rows){let e=rows.length;while(e>0&&rows[e-1].every(c=>!c.trim()))e--;const s=rows.slice(0,e);let cols=0;for(const r of s)for(let i=r.length-1;i>=0;i--)if(r[i]?.trim()){cols=Math.max(cols,i+1);break}return s.map(r=>r.slice(0,cols).map(c=>c.trim()))}
for (const f of fs.readdirSync(".").filter(f=>f.endsWith(".xlsx"))){const wb=new ExcelJS.Workbook();await wb.xlsx.readFile("./"+f);
 const sheets=wb.worksheets.map(ws=>{const n=Math.max(ws.columnCount,1);const rows=[];ws.eachRow({includeEmpty:true},row=>{const l=[];for(let c=1;c<=n;c++){const cell=row.getCell(c);if(cell.isMerged&&cell.master.address!==cell.address){l.push("");continue}l.push(cellText(cell.value))}rows.push(l)});return{name:ws.name,rows:trim(rows)}});
 fs.writeFileSync("./"+f.replace(".xlsx",".grid.json"),JSON.stringify(sheets));console.log(f,sheets.map(s=>s.name+":"+s.rows.length).join(" "))}
